#pragma once

#include <cstddef> // for size_t
#include <cstdint> // for uint32_t

namespace adapterremoval {

class buffer;

//! The compression level used for block/stream compression with isa-l
constexpr unsigned ISAL_COMPRESSION_LEVEL = 1;
//! The maximum compression level supported by libdeflate
constexpr unsigned MAX_COMPRESSION_LEVEL = 12;

/**
 * Returns buffer containing header for isa-l gzip stream. To be followed by one
 * or more compressed blocks generated by `deflate_block_isal_1`, with the last
 * block written with eof=true, and finally by the tail block generated by
 * `gzip_stream_tail_isal`.
 **/
buffer
gzip_stream_header_isal();

/**
 * Returns buffer containing tail end of isa-l deflate stream
 *
 * @param input_crc32 Combined CRC32 across all (uncompressed) input blocks
 * @param input_size Total size of all (uncompressed) input blocks
 **/
buffer
gzip_stream_tail_isal(uint32_t input_crc32, size_t input_size);

/**
 * Deflate `src` using isa-l with compression level 1, write the block into
 * `dst`, starting at `dst_offset`, and resize `dst` down to fit the content.
 * `eof` specifies if this is the final (or only) block in a stream.  The
 * deflate block must fit after `dst_offset` without growing `dst`.
 */
void
deflate_block_isal_1(const buffer& src,
                     buffer& dst,
                     size_t dst_offset,
                     bool eof);

/**
 * Deflate `src` using libdeflate with compression level 0-12, write the block
 * into `dst`, starting at `dst_offset`, and resize `dst` down to fit the
 * content. The deflate block must fit after `dst_offset` without growing `dst`.
 */
void
deflate_block_libdeflate(const buffer& src,
                         buffer& dst,
                         size_t dst_offset,
                         unsigned compression_level);

/**
 * Write uncompressed deflate block containing `src` into `dst`, starting at
 * `dst_offset`, and resize `dst` down to fit the content.  The deflate block
 * must fit after `dst_offset` without growing `dst`.
 */
void
deflate_block_uncompressed(const buffer& src, buffer& dst, size_t dst_offset);

/** Calculates CRC32 checksum for the provided buffer */
uint32_t
crc32(const buffer& buf, uint32_t initial = 0);

} // namespace adapterremoval
